// Toy pipeline: tokenize -> compile to bytecode -> interpret with feedback -> "optimize" when hot
const src = "a + b";
const tokens = src.split(/\s+/);                    // 1. scanner: text -> tokens
const bytecode = [["load", tokens[0]], ["load", tokens[2]], ["add"]];   // 2-3. parse + bytecode for "a + b"
console.log("source  :", src);
console.log("tokens  :", tokens.join(" | "));
console.log("bytecode:", bytecode.map(b => b.join(" ")).join("; "));
const feedback = { types: new Set(), calls: 0, tier: "Ignition" };
function run(env) {                                 // 4. interpreter records type feedback
  feedback.calls++;
  const st = [];
  for (const [op, arg] of bytecode) {
    if (op === "load") st.push(env[arg]);
    else { const y = st.pop(), x = st.pop(); feedback.types.add(typeof x + "+" + typeof y); st.push(x + y); }
  }
  if (feedback.calls === 3 && feedback.types.size === 1) feedback.tier = "TurboFan (assumes " + [...feedback.types] + ")"; // 5. hot
  return st.pop();
}
for (let i = 1; i <= 4; i++) console.log("call", i, "->", run({ a: i, b: 10 }), "tier:", feedback.tier);
// 6. a guard fails: new type seen, so we fall back (deoptimize)
const r = run({ a: "x", b: "y" });
if (feedback.types.size > 1) feedback.tier = "Ignition (deoptimized)";
console.log("call 5 ->", r, "tier:", feedback.tier);

