// Toy inline cache: one call site remembers the shapes (key lists) it has seen.
function makeSite() {
  const seen = [];
  return {
    load(obj) {
      const shape = Object.keys(obj).join(",");
      if (!seen.includes(shape)) seen.push(shape);   // learn a new shape
      return obj.area;
    },
    state() {                                        // V8 thresholds: 1, 2-4, more than 4
      const n = seen.length;
      return n === 0 ? "uninitialized" : n === 1 ? "monomorphic" : n <= 4 ? "polymorphic" : "megamorphic";
    },
  };
}
