// Toy speculative optimization: a "fast" version guarded by a type check, with a deopt counter.
function slowAdd(a, b) { return a + b; }            // generic: works for any types
let optimized = false, deopts = 0;
function fastAdd(a, b) {
  if (!optimized) return slowAdd(a, b);             // still in the interpreter tier
  if (!(Number.isInteger(a) && Number.isInteger(b))) { // guard on the assumption "both are integers"
    optimized = false; deopts++;                    // assumption broken -> deoptimize
    console.log("  guard failed for", JSON.stringify([a, b]), "-> back to generic code");
    return slowAdd(a, b);
  }
  return (a + b) | 0;                               // specialised integer path
}
