import java.util.*;

public class Main {
    public static void main(String[] args) {
        // Tracing GC idea: mark everything reachable from the roots, free the rest (cycles included).
        int[][] refs = {{1}, {2}, {1}, {4}, {3}, {}};   // object i points to the objects listed
        int[] roots = {0};
        boolean[] marked = new boolean[refs.length];
        Deque<Integer> stack = new ArrayDeque<>();      // mark phase: depth-first from the roots
        for (int r : roots) stack.push(r);
        while (!stack.isEmpty()) {
            int o = stack.pop();
            if (marked[o]) continue;
            marked[o] = true;
            for (int r : refs[o]) stack.push(r);
        }
        List<String> live = new ArrayList<>(), freed = new ArrayList<>();
        for (int i = 0; i < marked.length; i++) (marked[i] ? live : freed).add("" + i); // sweep phase
        System.out.println("references: [[1],[2],[1],[4],[3],[]] roots: [0]");
        System.out.println("live: " + String.join(",", live));
        System.out.println("freed: " + String.join(",", freed) + " (3 and 4 point at each other but no root reaches them)");
    }
}

