        int[][] refs = { new[] { 1 }, new[] { 2 }, new[] { 1 }, new[] { 4 }, new[] { 3 }, new int[0] };
        int[] roots = { 0 };
        bool[] marked = new bool[refs.Length];
        var stack = new Stack<int>();                   // mark phase: depth-first from the roots
        foreach (int r in roots) stack.Push(r);
        while (stack.Count > 0)
        {
            int o = stack.Pop();
            if (marked[o]) continue;
            marked[o] = true;
            foreach (int r in refs[o]) stack.Push(r);
        }
        var live = new List<string>(); var freed = new List<string>();
        for (int i = 0; i < marked.Length; i++) (marked[i] ? live : freed).Add(i.ToString()); // sweep phase
