// Leak by forgotten listener, then the fix with AbortController. Uses Node's EventTarget.
const bus = new EventTarget();                      // long-lived, like window
let fired = 0;
function mount(useCleanup) {
  const big = new Array(1000).fill(0);              // data the handler captures
  const ctl = new AbortController();
  // the handler closure keeps `big` reachable from the bus
  bus.addEventListener("tick", () => { fired += big.length > 0 ? 1 : 0; }, { signal: ctl.signal });
  return () => { if (useCleanup) ctl.abort(); };    // unmount: abort() removes the listener
}
function listeners() {                              // count handlers by dispatching one event
  fired = 0;
  bus.dispatchEvent(new Event("tick"));
  return fired;
}
for (let i = 0; i < 5; i++) mount(false)();         // unmount WITHOUT cleanup
console.log("after 5 leaky mounts, handlers on bus:", listeners());
for (let i = 0; i < 5; i++) mount(true)();          // unmount WITH abort()
console.log("after 5 clean mounts, handlers on bus:", listeners(), "(only the 5 old leaks remain)");

// Three-snapshot idea: count objects by kind after repeating an action; growth that never stops is a leak.
const cache = [];                          // the bug: a module-level array nobody trims
function openModal() {
  const modal = { id: cache.length, big: new Array(10).fill("x") };
  cache.push(modal);                       // retained forever (the path to the GC root)
  return modal;
}
function snapshot() { return { modals: cache.length }; }
const s1 = snapshot();                     // baseline
for (let i = 0; i < 7; i++) openModal();
const s2 = snapshot();                     // after N actions
for (let i = 0; i < 7; i++) openModal();
const s3 = snapshot();                     // after N more
