console.log("delta 1->2:", s2.modals - s1.modals, " delta 2->3:", s3.modals - s2.modals);
console.log(s3.modals - s2.modals > 0 ? "growth every round => leak: follow retainers" : "flat => no leak");
cache.length = 0;                          // the fix: bound or clear it
