// A benchmark harness that warms up, keeps a result sink, and compares variants fairly.
function sumLoop(a) { let s = 0; for (let i = 0; i < a.length; i++) s += a[i]; return s; }
function sumReduce(a) { return a.reduce((x, y) => x + y, 0); }
const inputs = [];                                   // varied inputs, not one constant
for (let k = 0; k < 4; k++) inputs.push(Array.from({ length: 1000 }, (_, i) => i + k));

function bench(name, fn) {
  let sink = 0;                                      // result sink: stops dead-code elimination
  for (let w = 0; w < 200; w++) sink += fn(inputs[w % 4]);   // warm-up, not timed
  const samples = [];
  for (let batch = 0; batch < 5; batch++) {          // several batches -> a distribution
    const t0 = process.hrtime.bigint();
    for (let i = 0; i < 2000; i++) sink += fn(inputs[i % 4]);
    samples.push(Number(process.hrtime.bigint() - t0));
  }
  samples.sort((a, b) => a - b);
  return { name, sink, median: samples[2] };
}
const results = [bench("loop", sumLoop), bench("reduce", sumReduce)];  // each variant has its own function
for (const r of results) console.log(r.name, "sink =", r.sink, "(timing taken:", r.median > 0, ")");
console.log("both variants agree:", results[0].sink === results[1].sink);
